using SimplePZMapmaker.Core;
using System.Text.Json;
public static class LinearGeographyTests {
 public static IEnumerable<(string,Action)> Cases(){
  yield return("source rasterization retains concave extensions and courtyard holes on every floor",()=>{
   foreach(var courtyard in new[]{false,true}){var b=new Building{X=20,Y=20,Width=24,Height=24,Kind="apartments"};b.Design=BuildingDesigner.Generate(b,3,17,"rect",1);List<List<(double X,double Y)>> rings=courtyard?[[ (20,20),(44,20),(44,44),(20,44),(20,20)],[(27,27),(37,27),(37,37),(27,37),(27,27)]]:[[(20,20),(44,20),(44,28),(29,28),(29,44),(20,44),(20,20)]];Check(ImportedBuildingGeometry.Apply(b,rings,out var reason),reason);Check(b.FootprintOrigin=="source-grid"&&b.Design.Shape=="custom","Source origin lost");foreach(var f in b.Design.Floors){Check(f.Cells[12*24+12]=='.',"Hole or concavity filled");Check(f.Cells[3*24+20]!='.'&&f.Cells[20*24+3]!='.',"Extension removed");}BuildingDesigner.Validate(b);}
  });
  yield return("disconnected resampled building source is skipped rather than replaced by a rectangle",()=>{
   var b=new Building{Width=20,Height=10};b.Design=BuildingDesigner.Generate(b,1,42);var previous=JsonSerializer.Serialize(b.Design);Check(!ImportedBuildingGeometry.Apply(b,[[(0,0),(8,0),(8,10),(0,10),(0,0)],[(12,0),(20,0),(20,10),(12,10),(12,0)]],out var reason)&&reason.Contains("Disconnected"),"Disconnected source was fabricated");Check(previous==JsonSerializer.Serialize(b.Design),"Failed import mutated original design");
  });
  yield return("source metadata keeps original geographic rings and reports bounded simplification",()=>{
   var ring=Enumerable.Range(0,900).Select(i=>(X:30+Math.Sin(i*Math.PI*2/900)*.001,Y:50+Math.Cos(i*Math.PI*2/900)*.001)).ToList();ring.Add(ring[0]);var b=new Building{SourceOutline=ImportedBuildingGeometry.Capture([ring],out var limited)};Check(limited&&b.SourceOutline[0].Count==512&&b.SourceOutline[0][0]==b.SourceOutline[0][^1],"Source evidence was lost or unbounded");ImportedBuildingGeometry.Validate(b);b.SourceOutline[0][1]=new(double.NaN,50);Reject(()=>ImportedBuildingGeometry.Validate(b));
  });
  yield return("complete GeoJSON building import retains source concavity holes and original coordinates",()=>{
   var reference=new WorldGeoReference{Bounds=new(){West=30,East=30.004,South=49.997,North=50},MetresPerTile=1};var projection=new GeographicProjection(reference,100,100);
   foreach(var hole in new[]{false,true}){List<List<(double X,double Y)>> rings=hole?[[(40,40),(64,40),(64,64),(40,64),(40,40)],[(47,47),(57,47),(57,57),(47,57),(47,47)]]:[[(40,40),(64,40),(64,48),(49,48),(49,64),(40,64),(40,40)]];var coordinates=rings.Select(r=>r.Select(p=>{var v=projection.Geographic(p.X,p.Y);return new[]{v.Longitude,v.Latitude};}).ToArray()).ToArray();var json=JsonSerializer.Serialize(new{type="FeatureCollection",features=new[]{new{type="Feature",id="source-footprint",properties=new Dictionary<string,string>{{"building","apartments"},{"building:levels","3"}},geometry=new{type="Polygon",coordinates}}}});var p=GeographicImporter.Import(json,MapGenerator.Generate(new(){Kind="blank"}),projection.SectionBounds(256,256),projection:projection).Project;var b=p.Buildings.Single();Check(b.SourceOutline.Count==(hole?2:1)&&b.SourceOutline[0][0].Longitude==coordinates[0][0][0]&&b.FootprintOrigin=="source-grid","Source rings lost or fabricated");Check(b.Design!.Floors.All(f=>f.Cells[(52-b.Y)*b.Width+52-b.X]=='.'),"Imported courtyard or concavity filled");ProjectValidator.Validate(p);}
  });
  yield return("geographic reimport retains manual source path correction without stale old road terrain",()=>{
   var reference=new WorldGeoReference{Bounds=new(){West=30,East=30.004,South=49.997,North=50},MetresPerTile=1};var projection=new GeographicProjection(reference,100,100);var coordinates=new[]{(20d,20d),(80d,20d)}.Select(p=>{var v=projection.Geographic(p.Item1,p.Item2);return new[]{v.Longitude,v.Latitude};}).ToArray();var json=JsonSerializer.Serialize(new{type="FeatureCollection",features=new[]{new{type="Feature",id="road-source",properties=new Dictionary<string,string>{{"highway","residential"}},geometry=new{type="LineString",coordinates}}}});var p=GeographicImporter.Import(json,MapGenerator.Generate(new(){Kind="blank"}),projection.SectionBounds(256,256),projection:projection).Project;var f=p.LinearFeatures.Single();f=JsonSerializer.Deserialize<LinearFeature>(JsonSerializer.Serialize(f))!;f.Points=[new(20,30),new(80,30)];f.Modified=true;p=LinearFeatureEditor.Put(p,f);var before=JsonSerializer.Serialize(p);var kept=GeographicImporter.Import(json,p,p.Bounds,preserveEdits:true,projection:projection).Project;Check(kept.LinearFeatures.Count==1&&kept.LinearFeatures[0].Modified&&kept.LinearFeatures[0].SourceId=="geo-road-source"&&kept.LinearFeatures[0].SourcePath.Count==2&&kept.LinearFeatures[0].SourcePath[0].Longitude==coordinates[0][0]&&kept.Terrain[30*256+40]==Terrain.Road&&kept.Terrain[20*256+40]==Terrain.Grass,"Reimport lost manual source path or left ghost terrain");Check(JsonSerializer.Serialize(p)==before,"Reimport mutated original");var removed=LinearFeatureEditor.Remove(kept,f.Id);Check(removed.Terrain[30*256+40]==Terrain.Grass,"Reimport manual underlay was not reversible");
  });
  yield return("original source railway import emits native cardinal artwork and bounded WGS84 evidence",()=>{
   var reference=new WorldGeoReference{Bounds=new(){West=30,East=30.004,South=49.997,North=50},MetresPerTile=1};var projection=new GeographicProjection(reference,100,100);var points=new[]{(20d,80d),(60d,80d)}.Select(p=>{var g=projection.Geographic(p.Item1,p.Item2);return new{lon=g.Longitude,lat=g.Latitude};}).ToArray();var json=JsonSerializer.Serialize(new{elements=new[]{new{type="way",id=77,tags=new Dictionary<string,string>{{"railway","rail"}},geometry=points}}});var p=GeographicImporter.Import(json,MapGenerator.Generate(new(){Kind="blank"}),projection.SectionBounds(256,256),projection:projection).Project;var f=p.LinearFeatures.Single();Check(f.Kind=="railway"&&f.SourceId=="osm-way-77"&&f.SourcePath.Count==2&&f.GeneratedDecorations.Count>60&&f.AssetSources.Values.All(v=>v=="game"),"Original railway geometry/artwork source lost");ProjectValidator.Validate(p);
  });
  yield return("linear editing restores underlay atomically and retains manual divergent terrain",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});var before=JsonSerializer.Serialize(p);var feature=new LinearFeature{Id="road-one",Width=4,Points=[new(20,20),new(80,20)]};var next=LinearFeatureEditor.Put(p,feature);Check(JsonSerializer.Serialize(p)==before&&next.Terrain[20*256+40]==Terrain.Road,"Put mutated input or failed to render");next.Terrain[20*256+40]=Terrain.Sand;TerrainEditMask.Mark(next,20*256+40);feature.Points=[new(20,30),new(80,30)];var moved=LinearFeatureEditor.Put(next,feature);Check(moved.Terrain[20*256+40]==Terrain.Sand&&moved.Terrain[20*256+50]==Terrain.Grass&&moved.Terrain[30*256+50]==Terrain.Road,"Replaying road lost manual terrain or old underlay");var removed=LinearFeatureEditor.Remove(moved,feature.Id);Check(removed.LinearFeatures.Count==0&&removed.Terrain[30*256+50]==Terrain.Grass&&removed.Terrain[20*256+40]==Terrain.Sand,"Removal did not preserve manual divergence");ProjectValidator.Validate(removed);
  });
  yield return("linear intersections remain connected after removing one contributing road",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});p=LinearFeatureEditor.Put(p,new(){Id="east",Points=[new(20,40),new(80,40)]});p=LinearFeatureEditor.Put(p,new(){Id="north",Points=[new(50,20),new(50,80)]});p=LinearFeatureEditor.Remove(p,"east");Check(p.Terrain[40*256+50]==Terrain.Road&&p.Terrain[40*256+30]==Terrain.Grass,"Intersection underlay erased the remaining road");
  });
  yield return("curved rivers and level-zero bridge deck preserve source water underlay",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});p=LinearFeatureEditor.Put(p,new(){Id="river",Kind="river",Width=10,Interpolation="catmull-rom",Points=[new(20,40),new(50,50),new(80,40)]});p=LinearFeatureEditor.Put(p,new(){Id="bridge",Kind="bridge",Width=4,Points=[new(50,30),new(50,70)]});Check(p.Terrain[50*256+50]==Terrain.Road,"Bridge deck not rendered");p=LinearFeatureEditor.Remove(p,"bridge");Check(p.Terrain[50*256+50]==Terrain.Water,"Removed bridge did not restore water");
  });
  yield return("railway native sprite providers and manually moved proxy artwork survive editing",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});var f=new LinearFeature{Id="rail",Kind="railway",Width=3,Points=[new(20,30),new(40,30)]};p=LinearFeatureEditor.Put(p,f);Check(p.Decorations.Count>=40&&p.LinearFeatures[0].AssetSources.Values.All(v=>v=="game"),"Railway artwork or source ownership missing");var edited=p.Decorations[0];edited.X=10;var id=edited.Id;p=LinearFeatureEditor.Remove(p,"rail");Check(p.Decorations.Count==1&&p.Decorations[0].Id==id&&p.Decorations[0].X==10,"Removing rail erased manual proxy edit");Reject(()=>LinearFeatureEditor.Put(p,new(){Kind="railway",Points=[new(20,20),new(40,40)]}));
  });
  yield return("linear work limits reject expensive changes without mutating the project",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank",Size=2048});var before=JsonSerializer.Serialize(p);Reject(()=>LinearFeatureEditor.Put(p,new(){Width=64,Points=[new(0,100),new(2048,100)]}));Check(JsonSerializer.Serialize(p)==before,"Rejected stroke mutated input");Reject(()=>LinearFeatureEditor.Put(p,new(){Points=[new(double.NaN,10),new(20,10)]}));
  });
 }
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Expected geography validation failure");}
}
